package com.nexushr.service; import com.nexushr.dto.RequestDtos.PayrollRequest; import com.nexushr.entity.*; import com.nexushr.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.math.*; import java.util.*;
@Service public class PayrollService { final PayrollRepository repo; final EmployeeRepository employees; public PayrollService(PayrollRepository r,EmployeeRepository e){repo=r;employees=e;} public List<Payroll> month(String m){return repo.findByPayrollMonthOrderByEmployeeEmployeeCode(m);} public List<Payroll> mine(String email,EmployeeService es){return repo.findByEmployeeIdOrderByPayrollMonthDesc(es.current(email).getId());} public Payroll create(UUID employeeId,PayrollRequest x){var e=employees.findById(employeeId).orElseThrow();var m=YearMonth.parse(x.month());var p=repo.findByEmployeeIdAndPayrollMonth(employeeId,m.toString()).orElseGet(Payroll::new);p.setEmployee(e);p.setPayrollMonth(m);p.setBasic(e.getBasicSalary());p.setAllowances(x.allowances()==null?BigDecimal.ZERO:x.allowances());p.setDeductions(x.deductions()==null?BigDecimal.ZERO:x.deductions());p.setNetPay(p.getBasic().add(p.getAllowances()).subtract(p.getDeductions()));p.setStatus(PayrollStatus.PROCESSED);p.setProcessedAt(LocalDateTime.now());return repo.save(p);}}
